        private static void HistoryText(Dictionary<string, Dictionary<string, string>> catalog, string key, string en, string es, string it, string zh)
        {
            var values = new[] { en, es, it, zh }; var languages = new[] { "en", "es", "it", "zh-CN" };
            for (var i = 0; i < languages.Length; i++) catalog[languages[i]]["history." + key] = values[i];
        }
